        rounding = 10,
        active_opacity = 1.0,
        inactive_opacity = 0.7,
        blur = {
            enabled = true,
            size = 3,
            passes = 3,
            new_optimizations = true,
            ignore_opacity = false,
            xray = true,
        },
        dim_special = 0.3,
    },
