    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-name 'DejaVuSansMono Nerd Font 10'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface document-font-name 'DejaVuSansMono Nerd Font 10'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface monospace-font-name 'DejaVuSansMono Nerd Font 9'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-antialiasing 'rgba'")
    hl.exec_cmd("gsettings set org.gnome.desktop.interface font-hinting 'full'")
